#include <bits/stdc++.h>
using namespace std;

void apply(vector<int>& p, int x, int y) {
    int n = p.size();
    // [0..x-1] [x..n-y-1] [n-y..n-1] -> [n-y..n-1] [x..n-y-1] [0..x-1]
    vector<int> np;
    for (int i = n-y; i < n; i++) np.push_back(p[i]);
    for (int i = x; i < n-y; i++) np.push_back(p[i]);
    for (int i = 0; i < x; i++) np.push_back(p[i]);
    p = np;
}

int main(){
    int n;
    scanf("%d",&n);
    vector<int> p(n);
    for(int i=0;i<n;i++) scanf("%d",&p[i]);

    vector<pair<int,int>> ops;

    // Place elements 1,2,...,n into positions 0,1,...,n-1
    for(int placed = 0; placed < n; placed++){
        int pos = -1;
        for(int i = placed; i < n; i++) if(p[i] == placed+1){ pos = i; break; }
        if(pos == placed) continue;

        // Step 1: Move element from pos to position (n-1)
        // Use x = pos+1, y = n-1-pos. But need x+y < n, i.e., pos+1+n-1-pos = n, not < n.
        // So use x = pos, y = n-1-pos when pos > 0 and n-1-pos > 0 and pos + n-1-pos = n-1 < n. Good!
        // After this op, element at pos moves to: suffix starts at pos+1..n-1 (length n-1-pos), then middle is [pos..pos] (length 1 with our element), then prefix [0..pos-1]
        // Wait: x=pos, y=n-1-pos. Suffix = p[pos+1..n-1], middle = p[pos..pos], prefix = p[0..pos-1]
        // Result: [p[pos+1..n-1], p[pos], p[0..pos-1]]. Element is at position n-1-pos.
        // Hmm, that's not n-1. Let me just move it to the end differently.

        if(pos != n-1 && pos > 0 && (n-1-pos) > 0) {
            // x=pos, y=n-1-pos => element goes to position y = n-1-pos... no, position y + 0 (middle has 1 elem) = n-1-pos
            // Actually element is at index pos. After op(pos, n-1-pos): new array = suffix[n-(n-1-pos)..n-1] + middle[pos..pos] + prefix[0..pos-1]
            // = p[pos+1..n-1] + p[pos] + p[0..pos-1]. Element at index (n-1-pos-1)+1 = n-1-pos. Not at end.
            // Use x=1, y=n-1-pos to bring it closer? Let me just use two ops to get element to 'placed'.
            int x = pos - placed, y = n - 1 - pos;
            if(x > 0 && y > 0 && x + y < n - placed) {
                // operate on subarray? No, we operate on whole array. Shift: treat placed elems as already done.
                // x includes the placed prefix. x = pos - placed, but prefix starts at 0...
                // Just do: x = pos+1, y = n-pos-1 won't work. Let me try x=1, y=n-pos-1 if valid.
            }
        }
        // Fallback: bring element to front, then to placed
        if(pos != placed && pos < n-1 && pos > 0) {
            ops.push_back({1, n-1-pos}); apply(p, 1, n-1-pos); // brings suffix to front
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        }
        if(pos != placed && pos > 0 && placed < n-1) {
            int y = n - pos; int x = placed > 0 ? placed : 1;
            if(x > 0 && y > 0 && x+y < n) { ops.push_back({x,y}); apply(p,x,y); }
            else if(placed==0 && pos < n-1) { ops.push_back({1, n-pos}); apply(p,1,n-pos); }
            for(int i=0;i<n;i++) if(p[i]==placed+1){pos=i;break;}
        }
        if(pos != placed) {
            // brute force: try all valid (x,y)
            for(int x=1;x<n && pos!=placed;x++) for(int y=1;x+y<n && pos!=placed;y++) {
                vector<int> tmp=p; apply(tmp,x,y);
                int np=-1; for(int i=0;i<n;i++) if(tmp[i]==placed+1){np=i;break;}
                if(np==placed){ops.push_back({x,y});p=tmp;pos=placed;}
            }
        }
    }

    printf("%d\n",(int)ops.size());
    for(auto&[x,y]:ops) printf("%d %d\n",x,y);
}
